package br.com.mathinclui.auth.security;
import org.junit.jupiter.api.Test; import org.mockito.ArgumentCaptor; import org.springframework.security.oauth2.jwt.*; import javax.crypto.spec.SecretKeySpec; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class JwtTokenServiceTest { @Test void shouldIssueAccessTokenWithRoleAndAccessTypeClaims(){var encoder=mock(JwtEncoder.class);when(encoder.encode(any())).thenReturn(Jwt.withTokenValue("signed-token").header("alg","HS256").claim("placeholder",true).build());var key=new SecretKeySpec("01234567890123456789012345678901".getBytes(),"HmacSHA256");var service=new JwtTokenService(encoder,key,900,604800);var token=service.issueAccess(new AuthPrincipal(7L,"Prof. Ana","ana@escola.com",SubjectType.PROFESSOR));var captor=ArgumentCaptor.forClass(JwtEncoderParameters.class);verify(encoder).encode(captor.capture());var claims=captor.getValue().getClaims();assertThat(claims.getClaims().get("token_type")).isEqualTo("access");assertThat(claims.getClaims().get("role")).isEqualTo("ROLE_PROFESSOR");assertThat(claims.getSubject()).isEqualTo("PROFESSOR:7");assertThat(token.value()).isEqualTo("signed-token");} }
